<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pdo=db();$bid=branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['toggle'])){$pdo->prepare("UPDATE users SET is_active=1-is_active WHERE id=? AND role='kasir' AND branch_id=?")->execute([(int)$_POST['toggle'],$bid]);}else{$id=(int)($_POST['id']??0);$name=trim($_POST['name']);$username=trim($_POST['username']);$password=$_POST['password']??'';if($id){$pdo->prepare("UPDATE users SET name=?,username=? WHERE id=? AND role='kasir' AND branch_id=?")->execute([$name,$username,$id,$bid]);if($password)$pdo->prepare("UPDATE users SET password=? WHERE id=? AND role='kasir' AND branch_id=?")->execute([password_hash($password,PASSWORD_DEFAULT),$id,$bid]);}else{$pdo->prepare("INSERT INTO users(name,username,password,role,branch_id) VALUES(?,?,?,'kasir',?)")->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$bid]);}flash('success','Akun kasir disimpan.');}redirect('/owner/kasir.php');}
$s=$pdo->prepare("SELECT id,name,username,is_active FROM users WHERE role='kasir' AND branch_id=? ORDER BY name");$s->execute([$bid]);$rows=$s->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT id,name,username FROM users WHERE id=? AND role='kasir' AND branch_id=?");$s->execute([(int)$_GET['edit'],$bid]);$edit=$s->fetch();}$pageTitle='Akun Kasir Cabang';$active='kasir';include __DIR__.'/../includes/header.php';?>
<div class="grid two-col"><section class="card"><h2><?=$edit?'Edit':'Tambah'?> kasir</h2><form method="post" class="form-grid" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="field full">Nama<input name="name" required value="<?=e($edit['name']??'')?>"></label><label class="field full">Username<input name="username" required value="<?=e($edit['username']??'')?>"></label><label class="field full">Kata sandi<input name="password" type="password" minlength="6" <?=$edit?'':'required'?>></label><button class="btn primary">Simpan akun</button></form></section><section class="card"><h2>Kasir cabang ini</h2><div class="table-wrap"><table class="table"><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small><?=e($r['username'])?></small></td><td><span class="badge <?=$r['is_active']?'':'off'?>"><?=$r['is_active']?'Aktif':'Nonaktif'?></span></td><td><div class="actions"><a class="btn soft sm" href="?edit=<?=$r['id']?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="btn danger sm" name="toggle" value="<?=$r['id']?>"><?=$r['is_active']?'Nonaktifkan':'Aktifkan'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php include __DIR__.'/../includes/footer.php';?>
